<?php
declare(strict_types=1);
$inboxPage=(string)file_get_contents(dirname(__DIR__).'/app/Controllers/PageController.php');
$inboxApi=(string)file_get_contents(dirname(__DIR__).'/app/Controllers/ApiController.php');
$inboxJs=(string)file_get_contents(dirname(__DIR__).'/public/assets/app.js');
ok(str_contains($inboxPage,'id="task-inbox-input"')&&str_contains($inboxPage,'id="task-inbox-add"')&&str_contains($inboxPage,'id="task-inbox-list"'),'Chat page exposes the persistent Task Inbox composer and queue list');
ok(str_contains($inboxApi,"'/api/task-inbox'")&&str_contains($inboxApi,"'/api/task-inbox/cancel'")&&str_contains($inboxApi,"'/api/task-inbox/mark-sent'")&&str_contains($inboxApi,"'/api/task-inbox/reprioritize'"),'Task Inbox API supports list, enqueue, cancellation and reprioritization routes');
ok(str_contains($inboxJs,"api('/api/task-inbox'")&&str_contains($inboxJs,"api('/api/task-inbox/cancel'")&&str_contains($inboxJs,'task_inbox_id:inboxDraftId')&&str_contains($inboxJs,"api('/api/task-inbox/reprioritize'"),'Chat UI loads, adds, cancels and reprioritizes queued messages through the API');
ok(str_contains($inboxJs,'function loadTaskInbox')&&str_contains($inboxJs,'data-inbox-insert')&&str_contains($inboxJs,'state.busy')&&str_contains($inboxJs,'state.inboxDraftMessage')&&str_contains($inboxJs,'pollChatJob')&&str_contains($inboxJs,'restoreActiveChatJob')&&str_contains($inboxJs,'renderChatJobResult')&&str_contains($inboxJs,"/api/chat/jobs/checkpoint?id=")&&str_contains($inboxJs,'state.activeJobId')&&str_contains($inboxJs,"api('/api/chat/jobs/interrupt'"),'Task Inbox remains independently usable while an AI response is in progress and restores active jobs when a chat is reopened');
ok(str_contains($inboxApi,"'/api/chat/jobs/execution-review'")&&str_contains($inboxApi,"'/api/chat/jobs/approvals/decision'")&&str_contains($inboxApi,"'/api/chat/jobs/resume'"),'Q012 review, approval-decision and safe conversation-resume API routes are exposed');
ok(str_contains($inboxJs,'renderExecutionReview')&&str_contains($inboxJs,'data-exec-approval')&&str_contains($inboxJs,'data-safe-resume')&&str_contains($inboxJs,'No previous tool calls were replayed'),'Chat UI presents plan/approval review and an explicit no-replay safe-resume action');
ok(str_contains($inboxApi,"'/api/chat/jobs/tools/execute'")&&str_contains($inboxApi,"'/api/chat/jobs/tool-result'"),'Q012 Task 5 exposes a CSRF-protected explicit tool execution API and job-bound result retrieval');
ok(str_contains($inboxJs,'data-exec-step')&&str_contains($inboxJs,'arguments_hash')&&str_contains($inboxJs,'Execute this step')&&str_contains($inboxJs,'exact arguments shown above'),'Execution review UI displays exact tool arguments and requires an explicit per-step execute action');
